function maxProfit(prices) {
  let lowest = Infinity; // the cheapest price so far
  let best = 0;
  for (const price of prices) {
    lowest = Math.min(lowest, price);
    best = Math.max(best, price - lowest);
  }
  return best;
}

const [n, ...prices] = input.trim().split(/\s+/).map(Number);
console.log(maxProfit(prices.slice(0, n)));

