#include <iostream>
#include <vector>

int maxProfit(const std::vector<int>& prices) {
    int lowest = prices[0];  // the cheapest price so far
    int best = 0;
    for (int price : prices) {
        lowest = std::min(lowest, price);
        best = std::max(best, price - lowest);
    }
    return best;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> prices(n);
    for (int i = 0; i < n; i++) {
        std::cin >> prices[i];
    }
    std::cout << maxProfit(prices) << "\n";
    return 0;
}

