package main

import "fmt"

func maxProfit(prices []int) int {
	lowest := prices[0] // the cheapest price so far
	best := 0
	for _, price := range prices {
		if price < lowest {
			lowest = price
		}
		if price-lowest > best {
			best = price - lowest
		}
	}
	return best
}

func main() {
	var n int
	fmt.Scan(&n)
	prices := make([]int, n)
	for i := range prices {
		fmt.Scan(&prices[i])
	}
	fmt.Println(maxProfit(prices))
}

